// 👑 THE OWNER'S FOLDERS (owner 2026-11-06), on the owner-only AGENTS desktop: open pools, pay sooner, reward the best, what to do when pools pay nothing, the spots his money works in, and the safety dials. All read and write the same ledger as Collective HQ. The server re-checks he is the owner on every call.
const rise = i => ({ initial: { opacity: 0, y: 10 }, animate: { opacity: 1, y: 0 }, transition: { delay: i * 0.05, duration: 0.24 } });
const nonce = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 10)}`;
const LEDGER_NOTE = 'This pays on the ledger. Withdrawals are off, so no money leaves the wallet yet.';
const Head = ({ icon: I, title, line }) => <header className="ofd-h"><I size={20} aria-hidden="true" /><span><h3>{title}</h3><small>{line}</small></span></header>;
const Seg = ({ value, set, opts, label, id }) => <span className="m-seg" role="group" aria-label={label}>{opts.map(([k, l]) => <button key={k} type="button" className={value === k ? 'active' : ''} aria-pressed={value === k} onClick={() => set(k)} data-testid={`${id}-${k}`}>{l}</button>)}</span>;
const Amount = ({ value, set, top, label, id }) => <div className="ofd-amt"><Slider aria-label={label} className="ofd-slider" minValue={0} maxValue={Math.max(1, top)} step={Math.max(0.01, top / 200)} value={Math.min(value, Math.max(1, top))} onChange={v => set(Number(v))} data-testid={`${id}-slider`}><Slider.Track><Slider.Fill /><Slider.Thumb /></Slider.Track></Slider><label><span>$</span><input className="m-input m-num" type="number" min="0" step="any" value={value} onChange={e => set(Math.max(0, Number(e.target.value) || 0))} aria-label={label} data-testid={`${id}-usd`} /></label></div>;

// 💸 Pay sooner, and reward the best.
export function PayFolder({ d, save, busy }) {
  const s = d.stake || {}; const agents = d.stakeAgents || []; const [source, setSource] = useState('compound'); const [usd, setUsd] = useState(0); const [token, setToken] = useState('USDC'); const [cat, setCat] = useState(''); const [gift, setGift] = useState(0); const [why, setWhy] = useState(''); const room = source === 'compound' ? s.compoundUsd : s.keepUsd; const waiting = agents.reduce((n, a) => n + (a.pointsLeft || 0), 0);
  return <Fx><div className="ofd" data-testid="ofd-pay"><Head icon={Gift} title="Pay and reward" line={LEDGER_NOTE} />
    <div className="hq-kpis">{[['WHAT COMPOUNDED', s.compoundUsd, 'Profit nobody took'], ['THE COLLECTIVE EARNED', s.keepUsd, 'Fees and its piece of each profit'], ['BOOST POINTS OUT', waiting, 'What every agent can still earn'], ['PAID SO FAR', s.paidUsd, 'Every cut paid']].map(([k, v, t], i) => <motion.article key={k} {...rise(i)} style={{ '--c': ['#ff8bd8', '#c58bff', '#ffc24d', '#3ee58a'][i] }} data-tip={t}><small>{k}</small><Roll v={v || 0} fmt={money} /></motion.article>)}</div>
    {d.payPaused ? <p className="ofd-warn" role="status" data-testid="ofd-paused"><CircleAlert size={15} aria-hidden="true" /> Payouts are stopped in Safety. A profit compounds until you turn them back on.</p> : null}
    <section className="hq-card" data-testid="ofd-early"><h4>PAY AGENTS SOONER<small>Shared by each one's cut, up to its points. Never from a stake</small></h4>
      <div className="ofd-row"><Seg value={source} set={setSource} opts={[['compound', 'From what compounded'], ['keep', 'From what we earned']]} label="Pay from" id="ofd-source" /><Seg value={token} set={setToken} opts={[['USDC', 'USDC'], ['SOL', 'SOL']]} label="Token" id="ofd-token" /></div>
      <Amount value={usd} set={setUsd} top={room || 0} label="How much to pay" id="ofd-early" />
      <button type="button" className="m-btn m-go" disabled={busy || !usd || usd > (room || 0) || !waiting} onClick={() => { save(null, { payEarly: { source, token, usd, nonce: nonce() } }); setUsd(0); }} data-tip={waiting ? 'Takes this from what you picked and adds it to agents\' earnings' : 'No agent has points to pay'} data-testid="ofd-early-go">Pay {money(usd)}</button></section>
    <section className="hq-card" data-testid="ofd-bonus"><h4>A BONUS FOR ONE AGENT<small>From what the Collective earned. It takes none of its points</small></h4>
      {agents.length ? <><select className="m-input" value={cat} onChange={e => setCat(e.target.value)} aria-label="Agent" data-testid="ofd-bonus-agent"><option value="">Pick an agent</option>{agents.map(a => <option key={a.id} value={a.id}>{a.name} · {a.x.toFixed(2)}x</option>)}</select>
        <Amount value={gift} set={setGift} top={s.keepUsd || 0} label="Bonus" id="ofd-bonus" /><input className="m-input" value={why} onChange={e => setWhy(e.target.value)} maxLength={120} placeholder="What for" aria-label="What the bonus is for" data-testid="ofd-bonus-why" />
        <button type="button" className="m-btn m-go" disabled={busy || !cat || !gift || gift > (s.keepUsd || 0)} onClick={() => { save(null, { bonus: { cat, token, usd: gift, why, nonce: nonce() } }); setGift(0); setWhy(''); }} data-testid="ofd-bonus-go">Give {money(gift)}</button></> : <p className="fch-nil">No agent has staked yet.</p>}</section>
    {d.payLog?.length ? <ol className="ofd-log" data-testid="ofd-log">{d.payLog.map((x, i) => <li key={`${x.at}${i}`}><b className="m-num">{money(x.usd)}</b><span>{x.kind === 'bonus' ? `Bonus to ${x.name}${x.why ? `: ${x.why}` : ''}` : `Paid early from ${x.source === 'keep' ? 'what we earned' : 'what compounded'}`}</span><small>{new Date(x.at * 1000).toLocaleDateString()}</small></li>)}</ol> : null}
  </div></Fx>;
}

// 🛟 What pays when pools do not, each with what it can really afford today.
export function FallbackFolder({ d, onPay }) {
  const s = d.stake || {}; const c = d.cfg || {}; const owed = (d.stakeAgents || []).reduce((n, a) => n + (a.pointsLeft || 0), 0);
  const PLANS = [['live', 'Profit only', 'ON NOW', 'Agents earn only when a pool pays. Safest for the Collective, and quiet when pools are flat.', s.profitUsd, 'Paid in by pools so far'], ['compound', 'Top up from what compounded', 'YOUR CALL', `Pays from profit you already kept. It slows compounding, and it can never touch a stake.`, s.compoundUsd, 'Can pay today'], ['keep', 'Top up from fees', 'YOUR CALL', `Agent wallet fees and top-ups help pay rewards. Your income shrinks by what you pay, and pools stay untouched.`, s.keepUsd, 'Can pay today'], ['bonus', 'Reward the best proofs', 'YOUR CALL', 'Hand-pick the top graded agents. Keeps the best agents sending while pools are flat.', s.keepUsd, 'Can pay today']];
  return <Fx><div className="ofd" data-testid="ofd-fallback"><Head icon={LifeBuoy} title="Fallbacks" line="When pools pay nothing, these are the ways left to reward agents. Each uses only profit or the Collective's own money." />
    <p className="ofd-big" data-tip="Every agent's points left"><small>BOOST POINTS OUT</small><Roll v={owed} fmt={money} /><em>Not a debt. It is the most they could still be paid if there is profit.</em></p>
    <ol className="ofd-plans">{PLANS.map(([k, t, tag, line, v, sub], i) => <motion.li key={k} {...rise(i)} data-testid={`ofd-plan-${k}`}><Chip className={`hq-chip${k === 'live' ? ' is-ok' : ''}`}>{tag}</Chip><b>{t}</b><p>{line}</p><span className="m-num">{money(v)}<small>{sub}</small></span>{k === 'live' ? null : <button type="button" className="m-btn" onClick={onPay} data-tip="Opens Pay and reward" data-testid={`ofd-plan-go-${k}`}>Set it up</button>}</motion.li>)}</ol>
    <section className="hq-card"><h4>EACH $100 OF PROFIT TODAY</h4><p className="hq-note is-plain">Agents {(d.stakeAgents || []).reduce((n, a) => n + (a.nowPct || 0), 0).toFixed(2)}% · the Collective {c.collectivePoolPct}% · the rest compounds.</p></section>
  </div></Fx>;
}

const yearly = rate => (Number(rate) || 0) * 365 * 100;
const VENUE_URL = { raydium: id => `https://raydium.io/clmm/create-position/?pool_id=${id}`, meteora: id => `https://app.meteora.ag/dlmm/${id}`, orca: id => `https://www.orca.so/pools/${id}` };
// How much a band of plus or minus w concentrates money against the whole price range (constant-product maths). Fees earned only while price sits inside it.
// What a price move does to a pair held half and half, before fees. The usual impermanent loss formula.
export const moveLoss = m => { const k = 1 + m / 100; return (2 * Math.sqrt(k)) / (1 + k) - 1; };
export const bandState = (price, low, high) => { if (!(price > 0) || !(low > 0) || !(high > low)) return null; if (price < low || price > high) return 'out'; const edge = Math.min(price - low, high - price) / (high - low); return edge < 0.12 ? 'edge' : 'in'; };
// 🎯 One pool as a ranging card: what it pays, how deep it is, and what each band would do on your money, from today's numbers.
// Money's pool, in the shape the one AutoRange desk reads. The same desk as Launch › Pools.
export const rangePool = r => { const stable = m => /^(EPjFWd|Es9vMF)/.test(String(m)); const sol = m => /^So1111/.test(String(m)); const hold = stable(r.mintY) ? r.mintX : stable(r.mintX) ? r.mintY : sol(r.mintY) ? r.mintX : sol(r.mintX) ? r.mintY : r.mintX; return { id: r.pool, hold, kind: r.venue === 'meteora' ? 'dlmm' : 'v3', meta: r.feePct != null ? `${r.feePct}%` : "", proto: r.venue, sym: r.name, tvl: r.tvl, vol: r.vol24 }; };
const AutoRangeDesk = lazy(() => import('../AutoRangeDesk').then(m => ({ default: m.AutoRangeDesk })));
function SpotCard({ r, added, busy, onAdd, money$ }) {
  const turnover = r.tvl ? r.vol24 / r.tvl : 0;
  return <motion.li className="ofd-card" layout data-testid={`ofd-spot-${r.pool}`}><header><b>{r.name}</b><small>{r.venue} · {r.feePct}% fee{r.step ? ` · step ${r.step}` : ''}{r.readOnly ? ' · read only, AutoRange cannot open here yet' : ''}</small></header>
    <div className="ofd-vitals"><span data-tip="Its live price from the venue"><small>PRICE</small><em className="m-num">{Number(r.price) ? Number(Number(r.price).toPrecision(5)) : '—'}</em></span><span data-tip="Money in the pool. Deeper is harder to move"><small>DEPTH</small><em className="m-num">{money(r.tvl)}</em></span><span data-tip="Traded in the last 24 hours"><small>24H VOLUME</small><em className="m-num">{money(r.vol24)}</em></span><span data-tip="Fees paid to the whole pool in the last 24 hours"><small>24H FEES</small><em className="m-num">{money(r.fees24)}</em></span><span data-tip="Volume against depth. Above 1x means money turned over more than once a day"><small>TURNOVER</small><em className="m-num">{turnover.toFixed(2)}x</em></span><span data-tip="Its last 24 hours of fees, as if every day were like it. Whole pool average. It ignores price moves"><small>FEE RATE, YEARLY</small><em className="m-num">{yearly(r.rate).toFixed(0)}%</em></span></div>
    <Suspense fallback={<div className="grow-wait" />}><AutoRangeDesk pool={rangePool(r)} amt={money$} /></Suspense>
    <div className="ofd-row"><button type="button" className="m-btn m-go" disabled={busy || added} onClick={onAdd} data-tip="Adds it to your plan and makes its folder. It moves no money" data-testid={`ofd-spot-add-${r.pool}`}>{added ? 'In your plan' : 'Add to plan'}</button>{VENUE_URL[r.venue] ? <a className="m-btn" href={VENUE_URL[r.venue](r.pool)} target="_blank" rel="noopener noreferrer" data-tip="Open the range here, by hand, from the Collective wallet" data-testid={`ofd-spot-open-${r.pool}`}>Open on {r.venue} ↗</a> : null}</div></motion.li>;
}
const PROCESS = [['Pick 2 or 3 spots', 'Compare the cards. Deep, busy pools with a coin you can hold through a fall.', true], ['Add them to your plan', 'Each gets its target part and its own desktop folder. Limits come from Safety.', true], ['Fund the Collective wallet', 'Only with what you can lose. Stakes and fees land here.', true], ['Open the range', 'Pools builds and simulates a Meteora pool before you sign. A Raydium or DLMM range opens on the venue, by hand.', 'hand'], ['Enter its band', 'Type low and high in its folder. The folder then reads the live price against it.', true], ['Re-center when it leaves', 'Its folder and the live floor show out of range. You move it on the venue, by hand. Auto moves wait for one small real test you sign off.', 'hand'], ['Claim fees to the Collective wallet', 'On the venue, by hand. Nothing here reads pool earnings yet.', 'hand'], ['Paste the transaction', 'The chain must show it landing. Then seats are paid, the Collective takes its piece, and the rest compounds.', true]];
function Process() {
  return <section className="hq-card" data-testid="ofd-process"><h4>HOW IT GOES, START TO PAID</h4><ol className="ofd-steps">{PROCESS.map(([t, d, st], i) => <motion.li key={t} {...rise(i)} className={st === 'hand' ? 'is-hand' : ''}><i className="m-num">{i + 1}</i><span><b>{t}</b><small>{d}</small></span><em>{st === 'hand' ? 'BY HAND' : 'WIRED'}</em></motion.li>)}</ol></section>;
}
const GrowLines = lazy(() => import('./MoneyCharts').then(m => ({ default: m.GrowLines })));
const GROW_COLORS = ['#b48cff', '#57c7ff', '#ffc24d', '#c58bff'];
const GROW_KINDS = [['all', 'Everything'], ['pool', 'Pools'], ['lend', 'Lending'], ['stake', 'SOL staking'], ['stock', 'Stocks']];
const KIND_WORD = { pool: 'POOL', lend: 'LENDING', stake: 'STAKING', stock: 'STOCK' };
const RISK_WORD = { none: ['NO PRICE RISK', 'Dollars only. It can still fail or lose its peg'], half: ['ONE COIN MOVES', 'Half sits in a coin that can fall, and range moves cost more'], both: ['BOTH COINS MOVE', 'Neither side is a dollar'], coin: ['MOVES WITH THE COIN', 'Its value goes up and down with the coin'] };
const WINDOWS = [[12, '12H'], [24, '24H'], [168, '7D'], [300, '12D']];
// What the money would have done over the last hours of these points: fees or interest, the cost of price moves, and what is left. Same maths for every option, so they compare.
export function curveOf(d, hours, money_) {
  const pts = (d?.points || []).slice(-(hours + 1)); if (pts.length < 2) return null; const a0 = pts[0].a; const b0 = pts[0].b; let earned = 0;
  const curve = pts.map((q, i) => { if (i) earned += (q.fee || 0) * money_; const r = q.a / a0; const k = q.b / b0; const base = d.single ? r : Math.sqrt(r * k); return { t: q.t, value: money_ * base + earned, moved: money_ * (base - 1) }; });
  const end = curve.at(-1); return { curve, earned, moved: end.moved, net: end.value - money_, hours: pts.length - 1 };
}
// A month of its earnings at this window's pace, split the way the deal splits a profit. Only fees or interest: a price move is never stretched into a month.
export function payOf(earned, hours, cutsPct, piecePct) {
  if (!(earned > 0)) return null; const month = earned / hours * 720; const piece = month * piecePct / 100; const agents = Math.min(month - piece, month * cutsPct / 100); return { month, agents, piece, back: month - piece - agents };
}
// The chart opens on the deepest of each kind that is really trading: a neutral start, not a pick.
const firstOf = rows => ['pool', 'lend', 'stake', 'stock'].map(k => rows.filter(r => r.kind === k && (k === 'stock' || r.per1k24 >= 0.05)).sort((a, b) => b.tvl - a.tvl)[0]?.id).filter(Boolean);
// 💰 One folder for the Collective's money: what is really there, every way it could work on real numbers, and what the same dollars would have done. It measures: the picks are yours.
// 📐 What a band really does on this pool: replayed on its real hours by `range_sim`. Numbers only. Measured across 30 real pools on unseen hours, an auto range did not beat a plain full range: stable pairs were the one steady result.
function BandBars({ name, doc, size }) {
  const bands = doc?.ranges?.bands || []; const test = doc?.ranges?.test; if (!bands.length) return null; const top = Math.max(1, ...bands.map(b => Math.abs(b.pct)));
  return <section className="hq-card grow-bands" data-testid="grow-bands"><h4>BANDS ON {name}<small>Replayed on its real hours, with a swap to recenter. The fee boost is an estimate</small></h4><ul>{bands.map((b, i) => <li key={b.width} style={{ '--i': i }} data-testid={`grow-band-${b.width}`}><b className="m-num">±{b.width}%</b><i className="grow-ruler" aria-hidden="true"><u style={{ transform: `scaleX(${b.inRange / 100})` }} /></i><small className="m-num">{Math.round(b.inRange)}% in range · {b.moves} moves</small><em className={`m-num ${b.pct >= 0 ? 'is-up' : 'is-dn'}`} data-tip={`On ${size < 1000 ? '$' + size : money(size)}`}>{b.pct >= 0 ? '+' : ''}{(size * b.pct / 100).toFixed(2)}</em></li>)}</ul><div className="grow-bench" aria-hidden="false"><span><small>JUST HOLDING</small><b className="m-num">{(size * bands[0].holdPct / 100).toFixed(2)}</b></span><span><small>FULL RANGE</small><b className="m-num">{(size * bands[0].fullPct / 100).toFixed(2)}</b></span>{test ? <span data-tip={`Band chosen on older hours, scored on ${test.hours} newer ones it never saw`}><small>ON UNSEEN HOURS ±{test.width}%</small><b className="m-num">{(size * test.pct / 100).toFixed(2)}</b></span> : null}</div><p className="grow-small" style={{ top: 0 }} data-testid="grow-note">{size <= 25 ? 'At this size, network fees and any position rent are not counted here and can take most of it. ' : ''}Past numbers promise nothing, and {top > 50 ? 'a number this large is more likely thin data than a real return.' : 'tight bands on volatile coins lost in real tests.'}</p></section>;
}
function GapStrip({ call }) {
  const [rows, setRows] = useState(null);
  useEffect(() => { let on = true; call('/familia-pools/gaps').then(j => on && setRows((j.gaps || j.rows || []).slice(0, 6))).catch(() => on && setRows([])); return () => { on = false; }; }, [call]);
  if (!rows?.length) return null;
  return <section className="hq-card grow-gaps" data-testid="grow-gaps"><h4>PRICE GAPS NOW<small>The same coin priced differently across its pools, after swap costs. Read only</small></h4><ul>{rows.map((g, i) => <li key={`${g.mint || g.symbol}-${i}`} style={{ '--i': i }}><b>{g.symbol || g.sym || 'Coin'}</b><i aria-hidden="true"><u style={{ transform: `scaleX(${Math.min(1, Math.abs(Number(g.net ?? g.gap ?? 0)) / 3)})` }} /></i><em className="m-num">{Number(g.net ?? g.gap ?? 0).toFixed(2)}%</em></li>)}</ul></section>;
}
// 🧭 THE BEST BY RISK (owner 2026-11-07: "a true dash that helps find the best to keep the Collective growing and paying out"). The top earners
// on the board are thin coin pools that can fall 90%, so one ranking would point at the riskiest. Four lanes, the best of each on today's
// real numbers, why it leads, and what $1K there would pay out. It ranks: the pick and the money stay the owner's.
const LANES = [
  ['steady', 'Steady dollars', 'No price risk. It can still fail or lose its peg', r => r.risk === 'none' && (r.tvl || 0) >= 1e6, '#b48cff'],
  ['stake', 'SOL staking', 'Moves with SOL. Pays for holding it', r => r.kind === 'stake' && (r.tvl || 0) >= 5e6, '#57c7ff'],
  ['deep', 'Deep pool fees', 'A busy pool over $2M deep. One or both coins move', r => r.kind === 'pool' && (r.tvl || 0) >= 2e6, '#ffc24d'],
  ['hot', 'Hot and risky', 'The top fees on the board, in thin coin pools that can fall hard', r => r.kind === 'pool' && (r.tvl || 0) >= 1e5, '#ff8fa3'],
];
export const bestByLane = rows => LANES.map(([k, t, risk, ok, col]) => { const all = (rows || []).filter(ok).sort((a, b) => b.per1k24 - a.per1k24); return { k, t, risk, col, best: all[0] || null, next: all.slice(1, 3), n: all.length }; });
const short$ = v => (v >= 1e6 ? `$${(v / 1e6).toFixed(1)}M` : v >= 1e3 ? `$${Math.round(v / 1e3)}K` : `$${Math.round(v || 0)}`);
function laneWhy(l, lanes) {
  const r = l.best; if (!r) return '';
  if (l.k === 'hot') { const deep = lanes.find(x => x.k === 'deep')?.best; return `Leads on fees${deep ? `, ${Math.round(r.per1k24 / Math.max(0.01, deep.per1k24))}x the deepest pool's pace` : ''}, in a ${short$(r.tvl)} pool. A small price fall wipes that out.`; }
  return `Leads its lane on today's pace${r.mean30 ? `; its 30-day average is ${r.mean30.toFixed(1)}%` : ''}.${l.next[0] ? ` Next: ${l.next[0].name} at $${l.next[0].per1k24.toFixed(2)} a day.` : ''}`;
}
function MoneyDash({ d, rows, rules, picks, onChart, onPlan, inPlan, busy, cutsPct }) {
  const st = d.stake || {}; const pot = rules?.score?.potUsd ?? 0; const ladder = rules?.score?.ladder || []; const next = ladder.find(x => x.pot > pot); const lanes = useMemo(() => bestByLane(rows), [rows]); const piece = d.cfg?.collectivePoolPct || 0;
  const kpis = [['STAKED', st.stakedUsd, 'What agents really sent, by the ledger'], ['COLLECTIVE KEEPS', st.keepUsd, "Fees that are the Collective's own"], ['POOL PROFIT', st.profitUsd, 'Profit that really landed'], ['PAID TO AGENTS', st.paidUsd, 'What agents have really been paid']];
  return <section className="mny" data-testid="money-dash">
    <div className="mny-kpis" data-testid="grow-real">{kpis.map(([k, v, t], i) => <motion.article key={k} {...rise(i)} data-tip={t}><small>{k}</small><b className="m-num"><Roll v={Number(v) || 0} fmt={money} /></b></motion.article>)}
      <motion.article {...rise(4)} className="mny-rung" data-tip="The pot decides today's top score. A bigger pot opens a higher top, so the best proofs can earn more"><small>NEXT TOP SCORE</small>{next ? <><b className="m-num">{next.top}</b><i aria-hidden="true"><u style={{ transform: `scaleX(${Math.min(1, pot / next.pot)})` }} /></i><em className="m-num">{short$(pot)} of {short$(next.pot)} pot</em></> : <b className="m-num">At the top</b>}</motion.article></div>
    <header className="mny-h"><h4>THE BEST BY RISK<small>Today's real numbers, before price moves. It ranks; the pick is yours</small></h4></header>
    {!rows ? <p className="fch-nil">reading every venue…</p> : <div className="mny-lanes">{lanes.map((l, i) => { const r = l.best; const pay = r ? payOf(r.per1k24 * 30, 720, cutsPct, piece) : null; return <motion.article key={l.k} {...rise(i)} className="mny-lane" style={{ '--c': l.col }} data-testid={`money-lane-${l.k}`}>
      <header><b>{l.t}</b><small>{l.n} on the board</small></header><p className="mny-risk">{l.risk}</p>
      {r ? <><h3 title={r.name}>{r.name}</h3><small className="mny-venue">{String(r.venue || '').replace(/-/g, ' ')}</small>
        <div className="mny-nums"><span><small>A DAY ON $1K</small><b className="m-num">${r.per1k24.toFixed(2)}</b></span><span><small>A YEAR</small><b className="m-num">{r.yearPct.toFixed(1)}%</b></span><span><small>DEPTH</small><b className="m-num">{short$(r.tvl)}</b></span></div>
        <p className="mny-why">{laneWhy(l, lanes)}</p>
        {pay ? <p className="mny-pay" data-tip="A month at today's pace on $1K, before price moves, split by today's rules">$1K for a month: <b className="m-num">{money(pay.month)}</b>. Agents {money(pay.agents)}, Collective {money(pay.piece)}</p> : null}
        <div className="mny-acts"><button type="button" className="m-btn" aria-pressed={!!picks?.includes(r.id)} onClick={() => onChart(r.id)} data-tip="Puts it on the chart below with its real history" data-testid={`money-chart-${l.k}`}>{picks?.includes(r.id) ? 'On the chart' : 'Chart it'}</button>{r.kind !== 'pool' ? <button type="button" className="m-btn m-go" disabled={busy || inPlan(r)} onClick={() => onPlan(r)} data-tip="Adds it to your plan. It moves no money" data-testid={`money-plan-${l.k}`}>{inPlan(r) ? 'In your plan' : 'Add to plan'}</button> : null}</div></> : <p className="fch-nil">Nothing in this lane today.</p>}
    </motion.article>; })}</div>}
  </section>;
}

export function GrowFolder({ d, save, busy, call, extra = null }) {
  const [rows, setRows] = useState(null); const [err, setErr] = useState(''); const [kind, setKind] = useState('all'); const [sort, setSort] = useState('day'); const [size, setSize] = useState(1000); const [hours, setHours] = useState(24); const [picks, setPicks] = useState(null); const [docs, setDocs] = useState({}); const [open, setOpen] = useState('');
  const pools = d.pools || []; const c = d.cfg || {}; const st = d.stake || {}; const used = pools.reduce((n, p) => n + (Number(p.targetPct) || 0), 0); const cutsPct = (d.stakeAgents || []).reduce((n, a) => n + (a.nowPct || 0), 0);
  const read = useCallback(() => { setErr(''); call('/admin/grow').then(j => { setRows(j.rows || []); setPicks(x => x || firstOf(j.rows || [])); }).catch(e => setErr(e.message)); }, [call]);
  useEffect(() => { read(); }, [read]);
  useEffect(() => { (picks || []).filter(id => !docs[id]).forEach(id => call(`/admin/grow/detail?id=${encodeURIComponent(id)}`).then(j => setDocs(x => ({ ...x, [id]: j }))).catch(e => setDocs(x => ({ ...x, [id]: { points: [], why: e.message } })))); }, [picks]);   // eslint-disable-line react-hooks/exhaustive-deps
  const shown = useMemo(() => (rows || []).filter(r => kind === 'all' || r.kind === kind).sort((a, b) => (sort === 'deep' ? b.tvl - a.tvl : sort === 'safe' ? (a.risk === 'none' ? 0 : 1) - (b.risk === 'none' ? 0 : 1) || b.per1k24 - a.per1k24 : b.per1k24 - a.per1k24)).slice(0, 24), [rows, kind, sort]);
  const toggle = id => setPicks(x => (x.includes(id) ? x.filter(y => y !== id) : [...x, id].slice(-4)));
  const series = (picks || []).map((id, i) => { const r = (rows || []).find(x => x.id === id); const doc = docs[id]; const m = doc ? curveOf(doc, hours, size) : null; return { id, name: r?.name || id, row: r, color: GROW_COLORS[i % 4], why: doc?.why, loading: !doc, ...(m || {}) }; }).filter(x => x.row);
  const drawn = series.filter(x => x.curve); const inPlan = r => pools.some(p => (r.kind === 'pool' ? p.address === r.id : p.pair === r.name.slice(0, 32)));
  const addPlan = r => save(null, planBody(r)); const rules = usePoolRules();
  return <Fx><div className="ofd" data-testid="ofd-grow"><Head icon={Sparkles} title="Money" line="What is really here, every way it could work, and what the same dollars would have done. Real numbers. The picks are yours: this is data, not advice, and past numbers promise nothing." />
    <MoneyDash d={d} rows={rows} rules={rules} picks={picks} onChart={id => setPicks(x => ((x || []).includes(id) ? x : [...(x || []), id].slice(-4)))} onPlan={addPlan} inPlan={inPlan} busy={busy} cutsPct={cutsPct} />
    <section className="hq-card" data-testid="grow-chart"><h4>WHAT {money(size)} WOULD HAVE DONE<small>after price moves. Opens on the deepest of each kind. Tick up to 4 below</small></h4>
      <div className="ofd-row"><Seg value={hours} set={setHours} opts={WINDOWS} label="Window" id="grow-win" /><Seg value={size} set={setSize} opts={[[5, '$5'], [25, '$25'], [100, '$100'], [1000, '$1K'], [10000, '$10K']]} label="Money" id="grow-money" /></div>
      {drawn.length ? <Suspense fallback={<div className="grow-wait" />}><GrowLines series={drawn} money={size} /></Suspense> : <div className="grow-wait">{series.length && series.every(x => !x.loading) ? 'No history to draw for these.' : 'Reading real history…'}</div>}
      <ul className="grow-results" data-testid="grow-results">{series.map(x => { const pay = x.curve ? payOf(x.earned, x.hours, cutsPct, c.collectivePoolPct || 0) : null; return <li key={x.id} style={{ '--c': x.color }} data-testid={`grow-result-${x.id}`}><header><i aria-hidden="true" /><b>{x.name}</b><button type="button" className="gtr-linkbtn" onClick={() => toggle(x.id)} aria-label={`Take ${x.name} off the chart`}>✕</button></header>
        {x.curve ? <><div className="grow-tiles"><span data-tip={x.row.kind === 'stock' ? 'A stock pays nothing for being held' : 'Fees or interest over this window'}><small>EARNED</small><b className="m-num is-up">{money(x.earned)}</b></span><span data-tip="What price moves did to the money"><small>PRICE MOVE</small><b className={`m-num ${x.moved < 0 ? 'is-dn' : 'is-up'}`}>{x.moved < 0 ? '−' : '+'}{money(Math.abs(x.moved))}</b></span><span data-tip="Earned plus the price move"><small>NET</small><b className={`m-num ${x.net < 0 ? 'is-dn' : 'is-up'}`}>{x.net < 0 ? '−' : '+'}{money(Math.abs(x.net))}</b></span></div>
          <small className="grow-pay" data-testid={`grow-pay-${x.id}`}>{pay ? `Earnings alone, a month at this pace: ${money(pay.month)}. Agents ${money(pay.agents)}, Collective ${money(pay.piece)}, ${money(pay.back)} back in.${x.net < 0 ? ' This window the price move cost more than it earned.' : ''}` : x.row.kind === 'stock' ? 'It pays nothing by being held. Only a sale higher makes a profit to share' : 'It earned nothing in this window, so it would have paid nobody'}</small></> : <small className="grow-pay">{x.loading ? 'Reading…' : x.why || 'Not enough history for this window.'}</small>}
        <div className="ofd-row">{x.row.kind === 'pool' ? <button type="button" className="gtr-linkbtn" onClick={() => setOpen(o => (o === x.id ? '' : x.id))} data-testid={`grow-band-${x.id}`}>What AutoRange bands would do</button> : <button type="button" className="m-btn" disabled={busy || inPlan(x.row)} onClick={() => addPlan(x.row)} data-tip="Adds it to your plan. It moves no money" data-testid={`grow-add-${x.id}`}>{inPlan(x.row) ? 'In your plan' : 'Add to plan'}</button>}{x.row.llama ? <a className="m-btn" href={`https://defillama.com/yields/pool/${x.row.llama}`} target="_blank" rel="noopener noreferrer">Its record ↗</a> : null}</div>
        </li>; })}</ul>
      {series.filter(x => open === x.id && x.row.pool).map(x => <ul key={x.id} className="ofd-cards grow-band" data-testid={`grow-band-open-${x.id}`}><SpotCard r={x.row.pool} money$={size} added={inPlan(x.row)} busy={busy} onAdd={() => addPlan(x.row)} /></ul>)}
      <p className="hq-note"><CircleAlert size={13} aria-hidden="true" /> Pools are measured as a plain whole-range position on today's depth. A tight band earns more and loses more. Interest and fees are paid in the venue's terms, and hacks, peg breaks and failures are not in these lines.</p></section>
    {series[0] && docs[series[0].id] ? <BandBars name={series[0].name} doc={docs[series[0].id]} size={size} /> : null}<GapStrip call={call} />
    <section className="hq-card" data-testid="grow-board"><h4>EVERY OPTION<small>{rows ? `${rows.length} read live` : 'reading…'}. Tick to put it on the chart</small><button type="button" className="m-btn ofd-re" onClick={read} aria-label="Read again" data-tip="Read them again"><RefreshCw size={13} aria-hidden="true" /></button></h4>
      <div className="ofd-row"><Seg value={kind} set={setKind} opts={GROW_KINDS} label="Kind" id="grow-kind" /><Seg value={sort} set={setSort} opts={[['day', 'Earned today'], ['deep', 'Deepest'], ['safe', 'No price risk first']]} label="Sort" id="grow-sort" /></div>
      {err ? <p className="lct-err" role="alert">⚠ {err}</p> : !rows ? <p className="fch-nil">reading every venue…</p> : <ul className="grow-list">{shown.map(r => <li key={r.id} className={picks?.includes(r.id) ? 'is-on' : ''} data-testid={`grow-row-${r.id}`}><label><input type="checkbox" checked={!!picks?.includes(r.id)} onChange={() => toggle(r.id)} aria-label={`Put ${r.name} on the chart`} data-testid={`grow-tick-${r.id}`} /><span className="grow-name"><b>{r.name}</b><small>{KIND_WORD[r.kind]} · {r.venue}{r.readOnly ? ' · read only' : ''}</small></span></label><span data-tip="Earned on $1,000 at the last day's pace, before price moves"><small>A DAY ON $1K</small><b className="m-num">{r.per1k24 ? `$${r.per1k24.toFixed(2)}` : '$0'}</b></span><span data-tip={r.rewardPct ? `${r.rewardPct}% of it is paid in reward tokens` : 'At today\'s pace, before price moves. Not a promise'}><small>A YEAR</small><b className="m-num">{r.yearPct}%</b></span><span data-tip="Money in it"><small>DEPTH</small><b className="m-num">{money(r.tvl)}</b></span><em className={`grow-risk is-${r.risk}`} data-tip={r.kind === 'stock' ? 'Tokenized stock. Its issuer\'s terms may bar US persons, and pooling members\' money into stocks needs your lawyer first' : RISK_WORD[r.risk][1]}>{RISK_WORD[r.risk][0]}</em></li>)}</ul>}</section>
    <section className="hq-card" data-testid="ofd-plan"><h4>YOUR PLAN<small>{used.toFixed(0)}% placed · {c.reservePct}% reserve · {Math.max(0, 100 - used - c.reservePct).toFixed(0)}% free</small></h4>
      <div className="ofd-stack" aria-hidden="true">{pools.filter(p => p.targetPct).map((p, i) => <u key={p.id} style={{ width: `${p.targetPct}%`, '--i': i }} data-tip={`${p.pair}: ${p.targetPct}%`} />)}<u className="is-res" style={{ width: `${c.reservePct}%` }} data-tip={`Reserve: ${c.reservePct}%`} /></div>
      {pools.length ? <ul className="ofd-targets">{pools.map(p => <li key={p.id} data-testid={`ofd-target-${p.id}`}><b>{p.pair}</b><small>{p.platform}{Number(p.inUsd) ? ` · $${p.inUsd} in` : ' · no money in yet'}</small><input className="m-input m-num" type="number" min="0" max={c.spotMaxPct} defaultValue={p.targetPct || 0} onBlur={e => { const v = Number(e.target.value) || 0; if (v !== (p.targetPct || 0)) save(null, { poolSet: { id: p.id, targetPct: v } }); }} aria-label={`Part of the plan for ${p.pair}`} data-testid={`ofd-target-input-${p.id}`} /><span>%</span><button type="button" className="m-btn" onClick={() => setOpen(o => (o === p.id ? '' : p.id))} aria-expanded={open === p.id} data-testid={`grow-plan-open-${p.id}`}>{open === p.id ? 'Close' : 'Numbers'}</button>{(rows || []).some(r => r.id === p.address) ? <button type="button" className="m-btn" onClick={() => setPicks(x => (x.includes(p.address) ? x : [...x, p.address].slice(-4)))} data-tip="Put it on the chart above" data-testid={`grow-plan-chart-${p.id}`}>Chart</button> : null}</li>)}</ul> : <p className="fch-nil">Nothing in your plan yet. A plan row holds no money until you put it there.</p>}
      {pools.filter(p => p.id === open).map(p => <PoolDesk key={p.id} p={p} d={d} save={save} busy={busy} />)}</section>
    <details className="grow-more" data-testid="grow-open-real"><summary>Open a real pool with the Collective wallet</summary>{extra}</details>
    <details className="grow-more"><summary>How it goes, start to paid</summary><Process /></details>
  </div></Fx>;
}

const SAFETY = [['walletCapPct', 'Most one wallet can hold', '%', 1, 'Across all its agents, so a whale or one person with many agents cannot crowd out others.'], ['reservePct', 'Reserve kept out of every spot', '%', 5, 'Your plan can never place this part. It covers losses and pays agents if a pool fails.'], ['spotMaxPct', 'Most in one spot', '%', 5, 'So one pool failing cannot take everything.'], ['minStakeUsd', 'Smallest stake that earns points', '$', 1, 'Stops farming with many tiny sends. A smaller send still stakes and earns no points. Sends already made keep what they earned.']];
const MISSING = [['AutoRange moves on the Collective wallet', 'Each pool folder watches its band live, but you move it by hand. Moving real money by itself waits for one small real test you approve.'], ['Profit read from pools', 'A profit counts when you paste its transaction. Nothing reads pool earnings by itself yet.'], ['Withdrawals', 'Off until a lawyer has checked the deal. Agents\' earnings stay on the ledger.'], ['A lawyer\'s answer', 'Money sent in, with rewards from pool profit, may count as an investment product.']];
// 🛡 The stop button, the limits and what stands between here and real payouts.
export function SafetyFolder({ d, save, busy, c, setC }) {
  const chain = d.chain; const short = chain?.short?.length; const stops = (d.pools || []).filter(p => (d.stops || []).includes(p.id));
  return <Fx><div className="ofd" data-testid="ofd-safety"><Head icon={ShieldCheck} title="Safety" line="What keeps every agent safe, from the first user to the 100,000th." />
    <div className="hq-chips"><Chip className={`hq-chip${short ? ' is-bad' : chain ? ' is-ok' : ''}`} data-tip="The real wallet against what it must hold, every 5 minutes">{!chain ? 'WALLET NOT READ YET' : short ? `SHORT IN ${chain.short.join(' + ')}` : 'FULLY COVERED'}</Chip><Chip className={`hq-chip${d.audit?.ok ? ' is-ok' : d.audit ? ' is-bad' : ''}`} data-tip="The whole ledger chain is walked every 5 minutes">{!d.audit ? 'CHAIN NOT WALKED YET' : d.audit.ok ? 'CHAIN UNBROKEN' : 'CHAIN BROKEN'}</Chip><Chip className="hq-chip">{d.held?.length || 0} PROOFS HELD</Chip></div>
    <section className="hq-card ofd-stop" data-testid="ofd-stop"><span><b>Stop all payouts</b><small>Profit keeps compounding and the Collective keeps its piece. No cut is paid until you turn this off.</small></span><Switch isSelected={!!d.payPaused} isDisabled={busy} onChange={v => save(null, { payPaused: v })} aria-label="Stop all payouts" data-testid="ofd-stop-switch"><Switch.Content><Switch.Control><Switch.Thumb /></Switch.Control></Switch.Content></Switch></section>
    {stops.length ? <p className="ofd-warn" role="alert" data-testid="ofd-stops"><CircleAlert size={15} aria-hidden="true" /> Past your stop: {stops.map(p => p.pair).join(', ')}. Nothing moves by itself. Open its folder.</p> : null}
    <section className="hq-card" data-testid="ofd-limits"><h4>THE LIMITS</h4><Dials d={d} save={save} busy={busy} c={c} setC={setC} rows={SAFETY} /></section>
    <section className="hq-card" data-testid="ofd-missing"><h4>NOT BUILT OR NOT DONE YET</h4><ul className="ofd-missing">{MISSING.map(([h, t]) => <li key={h}><b>{h}</b><small>{t}</small></li>)}</ul></section>
  </div></Fx>;
}

// 🏊 One pool's own folder. It appears on the desktop when the pool is listed or opened.
export function PoolDesk({ p, d, save, busy }) {
  const [sig, setSig] = useState(''); const [live, setLive] = useState(null); const left = (Number(p.inUsd) || 0) - (Number(p.lossUsd) || 0); const num = (k, l, tip, u) => <label className="ofd-field" data-tip={tip}><span>{l}</span><input className="m-input m-num" type="number" min="0" step="any" defaultValue={p[k] || 0} onBlur={e => { const v = Number(e.target.value) || 0; if (v !== (p[k] || 0)) save(null, { poolSet: { id: p.id, [k]: v } }); }} aria-label={l} data-testid={`ofd-pool-${k}`} /><i>{u}</i></label>;
  useEffect(() => { if (!p.address) return undefined; let on = true; const q = p.mint ? `mint=${encodeURIComponent(p.mint)}&reads=1` : 'top=1&reads=1'; const go = () => fetch(apiUrl(`/api/reputation/familia-pools/ranges?${q}`)).then(r => (r.ok ? r.json() : null)).then(j => { if (on) setLive((j?.pools || []).find(x => x.pool === p.address) || false); }).catch(() => on && setLive(false)); go(); const t = setInterval(go, 60000); return () => { on = false; clearInterval(t); }; }, [p.address, p.mint]);
  const st = live ? bandState(live.price, p.bandLow, p.bandHigh) : null;
  return <Fx><div className="ofd" data-testid={`ofd-pool-${p.id}`}><Head icon={Sparkles} title={p.pair} line={`${p.platform}${p.address ? ` · ${p.address}` : ''}`} />
    <div className="hq-kpis">{[['PROFIT PAID', p.profitUsd || 0, '#3ee58a', 'Profit this pool really paid'], ['MONEY IN', Number(p.inUsd) || 0, '#57c7ff', 'What you say you put in'], ['LOSS', Number(p.lossUsd) || 0, '#ff8fa3', 'What you say it has lost'], ['STILL WORKING', left, '#ffc24d', 'Money in, less loss']].map(([k, v, col, t], i) => <motion.article key={k} {...rise(i)} style={{ '--c': col }} data-tip={t}><small>{k}</small><Roll v={v} fmt={money} /></motion.article>)}</div>
    <section className="hq-card"><h4>ITS NUMBERS<small>Yours to keep current. Nothing reads them from the pool yet</small></h4><div className="ofd-fields">{num('inUsd', 'Money in', 'What the Collective put in this pool', '$')}{num('lossUsd', 'Loss so far', 'Include what price moves have cost', '$')}{num('targetPct', 'Part of the plan', 'Inside your Safety limits', '%')}{num('stopPct', 'Warn me at a loss of', 'A warning in Safety. Nothing sells by itself', '%')}</div>
      <div className="ofd-row"><button type="button" className={`m-btn${p.on ? ' is-on' : ''}`} disabled={busy} aria-pressed={!!p.on} onClick={() => save(null, { poolSet: { id: p.id, on: !p.on } })} data-tip={p.on ? 'Members see it. Tap to hide it' : 'Hidden from members. Tap to show it'} data-testid="ofd-pool-on">{p.on ? 'Open to members' : 'Closed'}</button>{p.address ? <a className="m-btn" href={`https://solscan.io/account/${p.address}`} target="_blank" rel="noopener noreferrer" data-tip="See it on Solscan">Solscan ↗</a> : null}</div></section>
    {p.address && p.mint ? <section className="hq-card" data-testid="ofd-autorange"><h4>HOW IT GROWS<small>The same AutoRange desk as Launch › Pools. It signs nothing until your wallet does</small></h4><Suspense fallback={<div className="grow-wait" />}><AutoRangeDesk pool={rangePool({ pool: p.address, mintX: p.mint, venue: p.platform, feePct: live?.feePct, name: p.pair, tvl: live?.tvl, vol24: live?.vol24 })} amt={Number(p.inUsd) || 100} /></Suspense></section> : null}
    <section className={`hq-card ofd-range${st ? ` is-${st}` : ''}`} data-testid="ofd-range"><h4>ITS RANGE<small>{live ? `Live price ${Number(Number(live.price).toPrecision(6))}` : live === false ? 'Its live price could not be read' : 'reading its price…'}</small></h4><div className="ofd-fields">{num('bandLow', 'Band low', 'The low end of the range you opened', '')}{num('bandHigh', 'Band high', 'The high end of the range you opened', '')}</div><p className="ofd-range-now" data-testid="ofd-range-state">{st === 'out' ? 'OUT OF RANGE. It earns nothing until you move it on the venue.' : st === 'edge' ? 'Near the edge of its band. A move is close.' : st === 'in' ? 'In range and earning.' : 'Enter its band to watch it here.'}</p>{live ? <div className="ofd-vitals"><span><small>DEPTH</small><em className="m-num">{money(live.tvl)}</em></span><span><small>24H VOLUME</small><em className="m-num">{money(live.vol24)}</em></span><span><small>24H FEES</small><em className="m-num">{money(live.fees24)}</em></span></div> : null}</section>
    <section className="hq-card"><h4>A PROFIT FROM THIS POOL</h4><form className="hq-profit" onSubmit={e => { e.preventDefault(); if (sig.trim()) { save(null, { profitSig: sig.trim(), pool: p.id }); setSig(''); } }}><input className="m-input" value={sig} onChange={e => setSig(e.target.value)} placeholder="Paste the transaction that brought it to the Collective wallet" aria-label="Profit transaction" data-testid="ofd-pool-sig" /><button type="submit" className="m-btn m-go" disabled={busy || !sig.trim()} data-tip="It counts once, and only if the chain shows it landing. Then cuts are paid" data-testid="ofd-pool-sig-go">Pay cuts</button></form></section>
  </div></Fx>;
}

// 🐍 The five py agents: how each really did, and what OSSY or G4 proposes after reading their code. Words only: it changes no code, and you decide.
const PROOF_WORD = { pow: 'PoW', pop: 'PoP', pob: 'PoB', poc: 'PoC', pos: 'PoStatic' };
export function PyAgentsFolder({ call }) {
  const [d, setD] = useState(null); const [busy, setBusy] = useState(''); const [err, setErr] = useState('');
  useEffect(() => { let on = true; call('/admin/py-agents').then(x => on && setD(x)).catch(e => on && setErr(e.message)); return () => { on = false; }; }, [call]);
  const ask = async who => { setBusy(who); setErr(''); try { setD(await call('/admin/py-agents', { method: 'POST', body: JSON.stringify({ who }) })); } catch (e) { setErr(e.message); } setBusy(''); };
  const apply = async kind => { setBusy(kind); setErr(''); try { setD(await call('/admin/py-agents', { method: 'POST', body: JSON.stringify({ apply: kind }) })); } catch (e) { setErr(e.message); } setBusy(''); };
  return <Fx><div className="ofd" data-testid="ofd-py"><Head icon={ShieldCheck} title="Py agents" line="The five that check every proof before it earns. OSSY and G4 read their code and record, and write what is weak. Nothing changes until you decide." />
    {err ? <p className="lct-err" role="alert">⚠ {err}</p> : null}
    <ol className="ofd-seats">{(d?.seats || []).map((r, i) => <motion.li key={r.k} {...rise(i)} data-testid={`ofd-seat-${r.k}`}><b>{r.name}</b><small>{r.does}</small><i aria-hidden="true"><u style={{ transform: `scaleX(${r.checked ? r.passed / r.checked : r.tried ? r.triedOk / r.tried : 0})` }} /></i><em className="m-num">{r.checked ? `${r.passed} of ${r.checked} real sends passed` : r.tried ? `Practice: ${r.triedOk} of ${r.tried} filed proofs pass` : 'Runs on the first real send'}</em>{r.lastNo || r.triedNo ? <q>{r.lastNo || r.triedNo}</q> : null}</motion.li>)}</ol>
    <div className="ofd-row">{[['ossy', 'Ask OSSY'], ['g4', 'Ask G4']].map(([k, l]) => <button key={k} type="button" className="m-btn m-go" disabled={!!busy} onClick={() => ask(k)} data-tip="Free, on your own machine. It can take a few minutes" data-testid={`ofd-py-${k}`}>{busy === k ? 'Reading their code…' : l}</button>)}</div>
    <section className="hq-card" data-testid="ofd-py-learn"><h4>WHAT THEY LEARN FROM OSSY AND G4<small>Each scored proof teaches them. New weights must beat proofs they never saw, and only you apply them</small></h4><ul className="ofd-learn">{(d?.learned || []).map(r => <li key={r.kind} data-testid={`ofd-learn-${r.kind}`}><b>{PROOF_WORD[r.kind] || r.kind}</b><i aria-hidden="true"><u style={{ transform: `scaleX(${Math.min(1, r.n / (r.need || 12))})` }} /></i><small className="m-num">{r.n} of {r.need} scored</small><em>{r.weights ? `Off by ${Math.round((r.mae || 0) * 100)}%, learned ${Math.round((r.learnedMae || 0) * 100)}%` : 'Learning'}</em>{r.ready ? <button type="button" className="m-btn m-go" disabled={!!busy} onClick={() => apply(r.kind)} data-tip="These weights did better on proofs they never saw. New scores use them" data-testid={`ofd-learn-apply-${r.kind}`}>Apply</button> : null}</li>)}</ul></section>
    {(d?.runs || []).map(run => <section key={run.at} className="hq-card" data-testid="ofd-py-run"><h4>{run.by.toUpperCase()} PROPOSES<small>{new Date(run.at * 1000).toLocaleString()}</small></h4><ul className="ofd-missing">{run.proposals.map((p, i) => <li key={i}><b>{p.seat} · {p.risk} risk</b><small>{p.weak}</small><small>Fix: {p.fix}</small></li>)}</ul></section>)}
  </div></Fx>;
}

// 🗂 One folder holding several jobs: a tab each, and only the open one runs.
// 🛠 A crash → the real file → an exact fix on its own branch, tested → your word. It never touches main or anything near money.
const FIX_STEPS = [['reading', 'Reads the file'], ['testing', 'Tests its fix'], ['picturing', 'Before / after'], ['review', 'Your review'], ['approved', 'Queued']];
// 📸 AGT-15: the broken screen (the running site) beside the same screen from the fix's own branch. Click one to see it big.
function FixPictures({ call, run, id }) {
  const [p, setP] = useState(null); const [big, setBig] = useState(null); const have = run.before || run.after;
  useEffect(() => { if (!have) return undefined; let on = true; call(`/admin/fix/pictures/${encodeURIComponent(id)}`).then(j => on && setP(j)).catch(() => {}); return () => { on = false; }; }, [call, id, have, run.before, run.after, run.at]);
  if (!have && !run.beforeWhy && !run.afterWhy) return null;
  const side = (k, label, why) => <figure className={`fix-pic is-${k}`} data-testid={`fix-pic-${k}-${id}`}><figcaption><b>{label}</b><small>{k === 'before' ? 'the running site' : `branch ${run.branch || ''}`}</small></figcaption>
    {p?.[k] ? <button type="button" className="fix-pic-img" onClick={() => setBig(k)} data-tip="See it big"><img src={p[k]} alt={`${label} screen`} loading="lazy" /></button> : <p className="fix-pic-nil">{why || (have ? 'loading…' : 'not taken yet')}</p>}</figure>;
  return <div className="fix-pics" data-testid={`fix-pics-${id}`}>{side('before', 'BEFORE', run.beforeWhy)}{side('after', 'AFTER', run.afterWhy)}
    {big && p?.[big] ? <button type="button" className="fix-pic-big" onClick={() => setBig(null)} aria-label="Close the big picture" data-testid="fix-pic-big"><img src={p[big]} alt={`${big} screen, big`} /></button> : null}</div>;
}
export function FixFolder({ call }) {
  const [d, setD] = useState(null); const [err, setErr] = useState(''); const [seat, setSeat] = useState('');
  const load = useCallback(() => call('/admin/fix').then(j => { setD(j); setSeat(x => x || j.seats?.[0]?.key || ''); }).catch(e => setErr(e.message)), [call]);
  useEffect(() => { load(); }, [load]); useEffect(() => { if (!d?.busy) return undefined; const t = setInterval(load, 3000); return () => clearInterval(t); }, [d?.busy, load]);
  const act = async body => { setErr(''); try { await call('/admin/fix', { method: 'POST', body: JSON.stringify(body) }); await load(); } catch (e) { setErr(e.message); } };
  if (!d) return <p className="fch-nil">{err || 'reading the crash log…'}</p>;
  return <div className="ofd" data-testid="fix-folder"><Head icon={LifeBuoy} title="Fix agent" line="A crash goes to the real file, a mind proposes one exact change on its own branch, and its checks run. Main and anything near money are never touched. You decide." />
    <div className="ofd-row"><span className="m-seg" role="group" aria-label="Which mind investigates">{(d.seats || []).map(x => <button key={x.key} type="button" className={seat === x.key ? 'active' : ''} aria-pressed={seat === x.key} onClick={() => setSeat(x.key)} data-tip={x.free ? 'Free, on your own LM Studio' : 'Spends a fraction of a cent of your OpenRouter credit. Smarter than the small local minds'} data-testid={`fix-seat-${x.key}`}>{x.name}{x.free ? '' : ' · paid'}</button>)}</span>{d.busy ? <em className="fix-busy m-num" role="status" data-testid="fix-busy">{d.busy.by} is working</em> : null}</div>
    {err ? <p className="lct-err" role="alert">⚠ {err}</p> : null}
    {d.cases?.length ? <ul className="fix-list">{d.cases.map(c => { const r = c.run; const now = FIX_STEPS.findIndex(x => x[0] === r?.stage); return <li key={c.id} className={r?.stage ? `is-${r.stage}` : ''} data-testid={`fix-${c.id}`}><header><span><b>{c.text.replace(/^\[[a-z ]+\]\s*(This page:\s*)?/i, '')}</b><small className="m-num">{c.times} time{c.times === 1 ? '' : 's'} · {c.page || 'a page'}</small></span>{!r || r.stage === 'failed' ? <button type="button" className="m-btn m-go" disabled={!!d.busy || !seat} onClick={() => act({ id: c.id, seat })} data-testid={`fix-go-${c.id}`}>{r ? 'Try again' : 'Investigate'}</button> : null}</header>
      {r ? <><ol className="fix-rail" aria-label="Where it is">{FIX_STEPS.map(([k, l], i) => <li key={k} className={i < now || r.stage === 'approved' ? 'is-done' : i === now ? 'is-on' : ''}><i aria-hidden="true" />{l}</li>)}</ol>
        {r.cause ? <p className="fix-cause"><b>{r.by}:</b> {r.cause}{r.sure != null ? <em className="m-num"> · {r.sure}% sure</em> : null}</p> : null}{r.why ? <p className="fix-why" data-testid={`fix-why-${c.id}`}>{r.why}</p> : null}
        {r.diff?.removed ? <pre className="fix-diff" data-testid={`fix-diff-${c.id}`}><span className="is-old">− {r.diff.removed}</span>{'\n'}<span className="is-new">+ {r.diff.added}</span></pre> : null}
        <FixPictures call={call} run={r} id={c.id} />
        {r.checks?.length ? <ul className="fix-checks">{r.checks.map(x => <li key={x.name} className={x.ok ? 'is-ok' : 'is-no'} data-tip={x.out || undefined}>{x.ok ? '✓' : '✕'} {x.name}</li>)}</ul> : null}
        {r.stage === 'review' ? <div className="ofd-row"><button type="button" className="m-btn m-go" onClick={() => act({ id: c.id, approve: true })} data-tip="Queues its branch for the engineer to merge. Nothing merges by itself" data-testid={`fix-approve-${c.id}`}>Approve</button><button type="button" className="m-btn" onClick={() => act({ id: c.id, drop: true })} data-testid={`fix-drop-${c.id}`}>Drop it</button><button type="button" className="m-btn" disabled={!!d.busy} onClick={() => act({ id: c.id, pictures: true })} data-tip="Takes the before and after screenshots again. The after one runs this branch for a few minutes" data-testid={`fix-pics-again-${c.id}`}>Retake pictures</button><small className="m-num">{r.branch}</small></div> : r.stage === 'approved' ? <small className="m-num">Queued as {r.build}. {r.branch}</small> : null}</> : null}</li>; })}</ul> : <p className="fch-nil" data-testid="fix-none">No crash logged. Nothing to fix.</p>}</div>;
}
export function FolderTabs({ tabs, at, setAt, id }) {
  const [own, setOwn] = useState(tabs[0]?.[0]); const now = at ?? own; const pick = setAt || setOwn; const open = tabs.find(t => t[0] === now) || tabs[0];
  return <div className="ofd-tabbed" data-testid={`ftabs-${id}`}><div className="m-seg ofd-tabs" role="tablist" aria-label={id}>{tabs.map(([k, l]) => <button key={k} type="button" role="tab" aria-selected={open[0] === k} className={open[0] === k ? 'active' : ''} onClick={() => pick(k)} data-testid={`ftab-${id}-${k}`}>{l}</button>)}</div><div key={open[0]} role="tabpanel">{open[2]}</div></div>;
}
// 🧹 The AGENTS desktop, by job (owner 2026-11-06: "some folders could be put in other folders smartly"). Nothing is gone: each old folder is a tab of the one it belongs with.
export function groupApps(agentApps = [], ownerApps = []) {
  const by = Object.fromEntries([...agentApps, ...ownerApps].map(a => [a.k, a])); const used = new Set();
  const folder = (k, ic, label, tip, parts) => { const tabs = parts.filter(([key]) => by[key]).map(([key, word]) => { used.add(key); return [key, word, by[key].body]; }); return tabs.length ? { k, ic, label, tip, body: <FolderTabs tabs={tabs} id={k} /> } : null; };
  const out = [by['own-grow'], folder('own-collective', '💎', 'Collective', 'Where it stands, what members see, and its limits', [['collective', 'HQ'], ['colony', 'What members see'], ['own-safety', 'Safety']]), folder('own-proofs', '🏆', 'Proofs', "Every agent's proofs, the sealed record, and the five that check them", [['pow', 'PoW folders'], ['stash', 'Stash'], ['own-py', 'Py agents']]), folder('own-setup', '⚙', 'Setup', 'Prompts, keys and who can buy an agent', [['prompts', 'Prompts'], ['own-fix', 'Fix agent'], ['ready', 'Providers'], ['slots', 'Agent slots']])];
  used.add('own-grow');
  return [...out.filter(Boolean), ...[...agentApps, ...ownerApps].filter(a => !used.has(a.k))];
}

// One ledger read for every owner folder. Adding a pool makes its folder on the next read.
export function useOwnerFolders(call, on = true) {
  const [d, setD] = useState(null); const [err, setErr] = useState(''); const [busy, setBusy] = useState(false); const [c, setC] = useState(null);
  useEffect(() => { if (!on) return undefined; let live = true; const go = () => { if (!document.hidden) call('/admin/collective').then(x => live && setD(x)).catch(e => live && setErr(e.message)); }; go(); const t = setInterval(go, 30000); return () => { live = false; clearInterval(t); }; }, [call, on]);
  useEffect(() => { if (d?.cfg) setC(d.cfg); }, [d?.cfg]);
  const save = useCallback(async (cfg, extra) => { setBusy(true); setErr(''); try { setD(await call('/admin/collective', { method: 'POST', body: JSON.stringify(cfg ? { cfg } : extra) })); } catch (e) { setErr(e.message); } finally { setBusy(false); } }, [call]);
  const wrap = body => <>{err ? <p className="lct-err" role="alert">⚠ {err}</p> : null}{d && c ? body : <p className="fch-nil">reading the ledger…</p>}</>;
  const [moneyTab, setMoneyTab] = useState('money'); const openPay = useCallback(() => setMoneyTab('pay'), []);
  if (!on) return [];
  return [
    { k: 'own-grow', ic: '💰', label: 'Money', tip: 'Owner only: what is really here, every way it could work, what the same dollars did, and how agents get paid', body: <FolderTabs id="own-grow" at={moneyTab} setAt={setMoneyTab} tabs={[['money', 'Money', wrap(d ? <GrowFolder d={d} save={save} busy={busy} call={call} extra={<div className="ofd"><ColonyPot call={call} /><Pools d={d} save={save} busy={busy} /></div>} /> : null)], ['pay', 'Pay + reward', wrap(d ? <PayFolder d={d} save={save} busy={busy} /> : null)], ['fallback', 'Fallbacks', wrap(d ? <FallbackFolder d={d} onPay={openPay} /> : null)]]} /> },
    { k: 'own-safety', ic: '🛡', label: 'Safety', tip: 'Owner only: stop payouts, the limits, and what is not built yet', body: wrap(d && c ? <SafetyFolder d={d} save={save} busy={busy} c={c} setC={setC} /> : null) },
    { k: 'own-fix', ic: '🛠', label: 'Fix agent', tip: 'Owner only: logged crashes, and a tested fix for each on its own branch', body: <FixFolder call={call} /> },
    { k: 'own-py', ic: '🐍', label: 'Py agents', tip: 'Owner only: the five validators, their real record, and what OSSY and G4 propose', body: <PyAgentsFolder call={call} /> },
  ];
}
